		const result = await workflow.execute("computer_apps", { pid: 1 });
		const text = result.content.find((item) => item.type === "text");
		const data = JSON.parse(text?.text ?? "{}");
		expect(data.items).toHaveLength(50);
		expect(data.omitted).toBe(1);
